    id: "scifi_titan_eel",
    name: "Titan Eel",
    subtitle: "Colossal Shock Sea Serpent",
    sourcebook: 'Sci-Fi Companion',
    classification: "Beast",
    isWildCard: true,
    size: 0,
    scale: "Normal",
    pace: "\u2014",
    parry: 7,
    toughness: 20,
